/* eslint-disable no-console -- a CLI generator reports to stdout */
/**
 * Regenerates the NCD catalog's manifest and source list.
 *
 * GENERATED, never hand-edited. A hand-maintained index of 250 feature codes is
 * a file that is wrong within a week, and an index nobody trusts is worse than
 * none — so it is derived from the catalog itself and regenerated by
 * `npm run ncd:manifest`. The CSO reads these two files; the catalog is what
 * they describe.
 *
 * Emits:
 *   docs/clinical/ncd/diabetes-exam-index.md    — every id, by section
 *   docs/clinical/ncd/diabetes-exam-sources.md  — every distinct source, with
 *                                                  what it is cited for
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import type { Citation, NcdCatalog } from "@/lib/ncd/catalog/schema";

import { DIABETES_CATALOG } from "@/lib/ncd/catalog/diabetes";
import { validateCatalog } from "@/lib/ncd/catalog/validate";

const OUT_DIR = join(process.cwd(), "docs", "clinical", "ncd");

/** Everything that carries a citation, paired with what it is cited FOR. */
function allCitations(c: NcdCatalog): { cite: Citation; where: string }[] {
  const out: { cite: Citation; where: string }[] = [];
  const add = (cite: Citation | undefined, where: string) => {
    if (cite) out.push({ cite, where });
  };
  for (const f of c.features) {
    add(f.citation, `feature ${f.code}`);
    add(f.importantNegative?.citation, `feature ${f.code} (important negative)`);
    add(f.dangerSign?.citation, `feature ${f.code} (danger sign)`);
    (f.discriminates ?? []).forEach((d) =>
      add(d.citation, `feature ${f.code} → ${d.condition} (${d.direction}, ${d.strength})`),
    );
    (f.ageRefRanges ?? []).forEach((r) => add(r.citation, `feature ${f.code} (${r.band} range)`));
  }
  c.diagnosis.forEach((s) => {
    add(s.citation, `diagnosis ${s.id}`);
    s.anyOf.forEach((x) => add(x.citation, `criterion ${x.id}`));
  });
  (c.classifications ?? []).forEach((x) => add(x.citation, `classification ${x.code}`));
  c.complications.forEach((x) => {
    add(x.citation, `complication ${x.code}`);
    x.establishedBy.forEach((e) => add(e.citation, `complication ${x.code} / ${e.id}`));
    (x.staging ?? []).forEach((st) => add(st.citation, `staging ${st.id}`));
    add(x.emergency?.citation, `complication ${x.code} (emergency action)`);
  });
  (c.validityCaveats ?? []).forEach((x) => add(x.citation, `validity caveat ${x.id}`));
  (c.therapyFlags ?? []).forEach((x) => add(x.citation, `therapy flag ${x.id}`));
  (c.interpretation ?? []).forEach((x) => add(x.citation, `interpretation ${x.id}`));
  (c.conditions ?? []).forEach((x) => add(x.citation, `condition ${x.code}`));
  (c.rules ?? []).forEach((x) => add(x.citation, `rule ${x.id}`));
  return out;
}

function indexMd(c: NcdCatalog): string {
  const issues = validateCatalog(c);
  const errors = issues.filter((i) => i.severity === "error");
  const warnings = issues.filter((i) => i.severity === "warning");

  const L: string[] = [
    `# ${c.display} — catalog manifest`,
    "",
    "> Generated by `npm run ncd:manifest`. Do not edit by hand.",
    "",
    `**Catalog version** ${c.version} · **features** ${c.features.length} · ` +
      `**conditions** ${(c.conditions ?? []).length} · **rules** ${(c.rules ?? []).length} · ` +
      `**complications** ${c.complications.length}`,
    "",
    `**Validation** ${errors.length} errors, ${warnings.length} warnings.`,
    "",
    "Every entry is `csoSigned: false` and carries `review_status: needs_clinical_signoff`",
    "semantics through that flag. Nothing here has been ratified threshold-by-threshold.",
    "",
  ];

  L.push("## Conditions the differential may rank", "");
  if ((c.conditions ?? []).length === 0) L.push("_None declared._", "");
  else {
    L.push("| code | display | establishes via | age bands |", "| --- | --- | --- | --- |");
    for (const x of c.conditions ?? []) {
      L.push(
        `| \`${x.code}\` | ${x.display} | ${x.complication ? "`" + x.complication + "`" : "—"} | ${(x.ageBands ?? ["all"]).join(", ")} |`,
      );
    }
    L.push("");
  }

  L.push("## Rules", "");
  if ((c.rules ?? []).length === 0) L.push("_None declared._", "");
  else {
    L.push(
      "| id | condition | posterior | urgency | confirm with |",
      "| --- | --- | --- | --- | --- |",
    );
    for (const r of c.rules ?? []) {
      L.push(
        `| \`${r.id}\` | \`${r.condition}\` | ${r.posterior} | ${r.urgency} | ${r.confirmWith.map((x) => "`" + x + "`").join(" ") || "—"} |`,
      );
    }
    L.push("");
  }

  L.push("## Features, by section", "");
  for (const s of c.sections) {
    const fs = c.features.filter((f) => f.section === s.id);
    if (!fs.length) continue;
    L.push(`### ${s.display} (\`${s.id}\`) — ${fs.length}`, "");
    L.push(
      "| code | kind | group | discriminates | age bands |",
      "| --- | --- | --- | --- | --- |",
    );
    for (const f of fs) {
      const disc = (f.discriminates ?? [])
        .map((d) => `${d.direction === "supports" ? "+" : "−"}${d.condition}`)
        .join(" ");
      L.push(
        `| \`${f.code}\` | ${f.kind} | ${f.group ?? (f.parent ? "prop of `" + f.parent + "`" : "—")} | ${disc || "—"} | ${(f.ageBands ?? ["all"]).join(", ")} |`,
      );
    }
    L.push("");
  }

  if (errors.length) {
    L.push("## Validation errors", "");
    errors.forEach((e) => L.push(`- \`${e.path}\` — ${e.message}`));
    L.push("");
  }
  return L.join("\n");
}

function sourcesMd(c: NcdCatalog): string {
  const cites = allCitations(c);
  // One row per distinct source, not per use: a reviewer checks a guideline
  // once and then wants to see everything resting on it.
  const byKey = new Map<string, { cite: Citation; uses: string[] }>();
  for (const { cite, where } of cites) {
    const key = `${cite.standard}|${cite.version}|${cite.title}`;
    const hit = byKey.get(key);
    if (hit) hit.uses.push(where);
    else byKey.set(key, { cite, uses: [where] });
  }

  const rows = [...byKey.values()].sort(
    (a, b) =>
      a.cite.standard.localeCompare(b.cite.standard) ||
      a.cite.version.localeCompare(b.cite.version),
  );
  const unverified = rows.filter((r) => r.cite.needsCsoInput);

  const L: string[] = [
    `# ${c.display} — sources`,
    "",
    "> Generated by `npm run ncd:manifest`. Do not edit by hand.",
    "",
    `${rows.length} distinct sources across ${cites.length} cited assertions. ` +
      `${unverified.length} carry \`needsCsoInput\` — an unverifiable value that says so out loud.`,
    "",
    "## Sources",
    "",
  ];

  for (const { cite, uses } of rows) {
    L.push(`### ${cite.standard} — ${cite.title}`, "");
    L.push(`- **Edition/version:** ${cite.version}`);
    if (cite.retrieved) L.push(`- **Retrieved:** ${cite.retrieved}`);
    L.push(`- **Locator:** ${cite.url ? `<${cite.url}>` : "_none — see below_"}`);
    L.push(`- **CSO signed:** ${cite.csoSigned ? "yes" : "**no — gated dark**"}`);
    if (cite.quote) L.push(`- **Quote:** "${cite.quote}"`);
    if (cite.needsCsoInput) L.push(`- **Needs CSO input:** ${cite.needsCsoInput}`);
    L.push(
      `- **Cited for (${uses.length}):** ${uses.slice(0, 12).join("; ")}` +
        (uses.length > 12 ? ` … and ${uses.length - 12} more` : ""),
    );
    L.push("");
  }

  return L.join("\n");
}

function write(name: string, body: string) {
  const path = join(OUT_DIR, name);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, body.endsWith("\n") ? body : body + "\n");
  console.log(`wrote ${path} (${body.split("\n").length} lines)`);
}

write("diabetes-exam-index.md", indexMd(DIABETES_CATALOG));
write("diabetes-exam-sources.md", sourcesMd(DIABETES_CATALOG));
